
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_wl_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_wl", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.428548107461976e-02, -6.321046672141886e-02, -6.167676185238924e-02, -5.949669474010419e-02, -5.641489745830605e-02, -5.209567380201280e-02, -4.612836101990569e-02, -3.809913897155985e-02, -2.788256018017275e-02, -1.667839928978889e-02, -1.102699010394625e-02, -3.170591921169770e-02, -5.571823728360113e-02, -3.249667362914723e-02, -1.525605102500818e-02, -2.064361009197354e-03, 5.295358017876438e-03, 5.835607331141869e-03, 3.044196593452118e-03, 9.822928179665116e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


